import test from 'node:test';import assert from 'node:assert/strict';import {webcrypto} from 'node:crypto';
import {createCacheVault,CACHE_MAX,CACHE_AGE} from '../../src/features/cache/vault.ts';
const owner='00000000-0000-4000-8000-000000000001',other='00000000-0000-4000-8000-000000000002',origin='https://'+'a'.repeat(20)+'.supabase.co';
async function fixture(){let raw=null,time=1000;const key=await webcrypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']);const ports={read:async()=>raw,write:async v=>{raw=v;},remove:async()=>{raw=null;},encrypt:async(bytes,context)=>{const iv=webcrypto.getRandomValues(new Uint8Array(12)),cipher=new Uint8Array(await webcrypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode(context)},key,bytes));return new Uint8Array([...iv,...cipher]);},decrypt:async(bytes,context)=>new Uint8Array(await webcrypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(0,12),additionalData:new TextEncoder().encode(context)},key,bytes.slice(12)))};return{ports,vault:createCacheVault(origin,ports,()=>time),bytes:()=>raw,corrupt(){raw[13]^=1;},tick(ms){time+=ms;}};}
test('encrypted device snapshot survives a new vault without plaintext canaries',async()=>{const f=await fixture(),data={description:'SYNTHETIC_PRIVATE_CANARY',cents:29};assert.equal(await f.vault.save(owner,data),true);assert.equal(new TextDecoder().decode(f.bytes()).includes(data.description),false);assert.deepEqual(await createCacheVault(origin,f.ports,()=>1000).load(owner),{savedAt:1000,data});});
test('tampering and wrong user/project cannot restore cache',async()=>{const f=await fixture();await f.vault.save(owner,{cents:39});assert.equal(await f.vault.load(other),null);assert.equal(await createCacheVault('https://'+'b'.repeat(20)+'.supabase.co',f.ports,()=>1000).load(owner),null);f.corrupt();assert.equal(await f.vault.load(owner),null);});
test('expired oversized and invalid owner values are refused',async()=>{const f=await fixture();assert.equal(await f.vault.save('bad',{}),false);assert.equal(await f.vault.save(owner,'x'.repeat(CACHE_MAX)),false);await f.vault.save(owner,{});f.tick(CACHE_AGE+1);assert.equal(await f.vault.load(owner),null);});
test('logout clear fences an in-flight encryption so cache cannot resurrect',async()=>{const f=await fixture();let resume;const gate=new Promise(r=>resume=r),ports={...f.ports,encrypt:async(...a)=>{await gate;return f.ports.encrypt(...a);}};const vault=createCacheVault(origin,ports,()=>1000),save=vault.save(owner,{description:'PRIVATE'});await new Promise(r=>setImmediate(r));const clear=vault.clear();resume();assert.equal(await save,false);await clear;assert.equal(f.bytes(),null);});
test('storage unavailable has no plaintext fallback',async()=>{const f=await fixture(),vault=createCacheVault(origin,{...f.ports,encrypt:async()=>{throw Error('native_unavailable');}},()=>1000);assert.equal(await vault.save(owner,{cents:29}),false);assert.equal(f.bytes(),null);});
